DROP TABLE IF EXISTS `tbl_courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` text NOT NULL,
  `level` varchar(50) NOT NULL,
  `lesson` int(11) NOT NULL,
  `price` double NOT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `total_time_finish` varchar(255) NOT NULL,
  `finish_time` varchar(255) NOT NULL,
  `thumbnail` text DEFAULT NULL,
  `expiration_date` int(11) NOT NULL,
  `list_chapter` text NOT NULL,
  `rate` double DEFAULT 0,
  `student_enrolled` int(11) NOT NULL DEFAULT 0,
  `status` enum('Complete','Uncomplete') NOT NULL,
  `is_free` tinyint(1) NOT NULL DEFAULT 0,
  `is_popular` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tbl_courses_category_id_foreign` (`category_id`),
  CONSTRAINT `tbl_courses_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `tbl_categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
