DROP TABLE IF EXISTS `tbl_lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_lessons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` text NOT NULL,
  `id_course` bigint(20) unsigned NOT NULL,
  `url` text NOT NULL,
  `is_preview` tinyint(1) NOT NULL DEFAULT 0,
  `time` varchar(20) NOT NULL,
  `chapter` text NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tbl_lessons_id_course_foreign` (`id_course`),
  CONSTRAINT `tbl_lessons_id_course_foreign` FOREIGN KEY (`id_course`) REFERENCES `tbl_courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=927 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
