DROP TABLE IF EXISTS `tbl_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_messages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_sender` bigint(20) unsigned NOT NULL,
  `id_receiver` bigint(20) unsigned NOT NULL,
  `status` enum('removed','exist') NOT NULL DEFAULT 'exist',
  `content` text NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tbl_messages_id_sender_foreign` (`id_sender`),
  KEY `tbl_messages_id_receiver_foreign` (`id_receiver`),
  CONSTRAINT `tbl_messages_id_receiver_foreign` FOREIGN KEY (`id_receiver`) REFERENCES `tbl_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tbl_messages_id_sender_foreign` FOREIGN KEY (`id_sender`) REFERENCES `tbl_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

